const contents=$('READ — 04_CONTEUDOS').all().map(i=>i.json), media=$('READ — 03_MIDIAS').all().map(i=>i.json);
const norm=x=>String(x??'').trim(), up=x=>norm(x).toUpperCase();
const counts=new Map(), mediaCounts=new Map();
for(const c of contents){const k=norm(c.ID_CONTEÚDO);if(k)counts.set(k,(counts.get(k)||0)+1)}
for(const m of media){const k=norm(m.ID_MIDIA);if(k)mediaCounts.set(k,(mediaCounts.get(k)||0)+1)}
const chosen=contents.filter(c=>up(c.EDIT_SESSION_STATUS)==='SAVED'&&up(c.REVISION_MODE)==='MANUAL_EDIT'
    &&up(c.PIPELINE_STATE)==='EDIT_SESSION_READY');
const gated=$('ASSERT — RENDER READINESS').all().map(i=>i.json),approved=new Set(gated.map(x=>x.edit_session_id));
if(!chosen.length||gated.length!==chosen.length||approved.size!==chosen.length||
   chosen.some(c=>!approved.has(norm(c.EDIT_SESSION_ID))||
      !gated.some(g=>g.edit_session_id===norm(c.EDIT_SESSION_ID)&&
        g.preflight_contract==='SM3_07F_PREFLIGHT_V2')))
  throw new Error('SM3_07F_PREFLIGHT_BYPASS_OR_STATE_CHANGED');
const queue=new Map();
for(const c of chosen){
  const content=norm(c.ID_CONTEÚDO),project=norm(c.ID_PROJETO),session=norm(c.EDIT_SESSION_ID);
  if(counts.get(content)!==1||!/^TATTOO_[A-Za-z0-9_-]+$/.test(project)||
     !/^ES_[A-Za-z0-9_-]+$/.test(session)||up(c.STATE_VERSION)!=='SM3_STATE_V5'||
     norm(c.EDIT_RECIPE_VERSION)!=='SM3_EDIT_RECIPE_V1'||
     norm(c.PRODUCTION_CONTRACT_VERSION)!=='SM3_PRODUCTION_EDIT_V1')
     throw new Error('SM3_07F_SHEET_CONTROL_INVALID:'+content);
  const ids=[...new Set(norm(c.BRUTOS_USADOS).match(/M\d{4,}/g)||[])];
  if(!ids.length)throw new Error('SM3_07F_MEDIA_IDS_MISSING:'+content);
  for(const id of ids){
    if(mediaCounts.get(id)!==1)throw new Error('SM3_07F_MEDIA_REGISTRY_NOT_UNIQUE:'+id);
    const m=media.find(x=>norm(x.ID_MIDIA)===id);
    if(!norm(m.DRIVE_FILE_ID))throw new Error('SM3_07F_DRIVE_ID_MISSING:'+id);
    const safe=norm(m.ARQUIVO||id+'.bin').replace(/[^A-Za-z0-9._-]+/g,'_').slice(-100);
    const tipo=norm(m.TIPO).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();
    const mime=norm(m.MIME_TYPE).toLowerCase(),ext=(safe.toLowerCase().match(/\.([a-z0-9]+)$/)||[])[1];
    const video=['mp4','mov','m4v','avi','mkv','webm','3gp','mts','mpeg','mpg','wmv','flv','ts'].includes(ext);
    const image=['jpg','jpeg','png','webp','bmp','tif','tiff','heic','heif','avif','gif'].includes(ext);
    if(!(video||image||mime.startsWith('video/')||mime.startsWith('image/')))
       throw new Error('SM3_07F_MEDIA_TYPE_UNSUPPORTED:'+id);
    const kind=(video||mime.startsWith('video/')||tipo==='VIDEO')?'video':'image';
    const path='/data/media/inbox/edit_'+id+'_'+safe;
    if(!queue.has(id))queue.set(id,{route:'DOWNLOAD',ID_MIDIA:id,DRIVE_FILE_ID:norm(m.DRIVE_FILE_ID),
                                      ARQUIVO:norm(m.ARQUIVO||safe),kind,worker_source_path:path});
  }
}
return [...queue.values()].map(json=>({json}));

const written=$input.all().map(i=>i.json),contents=$('READ — 04_CONTEUDOS').all().map(i=>i.json),
  map=new Map(written.map(x=>[String(x.ID_MIDIA),x])),
  registry=$('READ — 03_MIDIAS').all().map(i=>i.json);
const chosen=contents.filter(c=>String(c.EDIT_SESSION_STATUS||'').trim().toUpperCase()==='SAVED'
  &&String(c.REVISION_MODE||'').trim().toUpperCase()==='MANUAL_EDIT'
  &&String(c.PIPELINE_STATE||'').trim().toUpperCase()==='EDIT_SESSION_READY');
return chosen.map(c=>{
  const ids=[...new Set(String(c.BRUTOS_USADOS||'').match(/M\d{4,}/g)||[])];
  const sources=ids.map(id=>map.get(id));
  if(!ids.length||sources.some(x=>!x))throw new Error('SM3_07F_SOURCE_WRITE_INCOMPLETE:'+c.ID_CONTEÚDO);
  return {json:{project_id:String(c.ID_PROJETO),content_id:String(c.ID_CONTEÚDO),
    edit_session_id:String(c.EDIT_SESSION_ID),sheet_render_status:String(c.RENDER_STATUS||'').trim(),
    source_media:sources.map(x=>{
      const rows=registry.filter(m=>String(m.ID_MIDIA).trim()===String(x.ID_MIDIA));
      const expected_sha256=String(rows[0]?.CONTENT_HASH||'').trim().toLowerCase();
      if(rows.length!==1||!(/^[a-f0-9]{64}$/.test(expected_sha256)))
        throw new Error('SM3_07F_SOURCE_HASH_PROVENANCE_INVALID:'+x.ID_MIDIA);
      return {media_id:x.ID_MIDIA,kind:x.kind,source_path:x.worker_source_path,
        file_name:x.ARQUIVO,expected_sha256};
    })}};
});

const w=$json, job=$('BUILD — EDIT PREVIEW JOBS').all().map(i=>i.json).find(x=>x.edit_session_id===w.edit_session_id);
if(!job||w.ok!==true||w.status!=='SAVED'||w.current_revision<2||w.read_only!==false||
   w.workspace_contract_version!=='SM3_EDITOR_WORKSPACE_V1'||
   !/^[a-f0-9]{64}$/.test(String(w.state_etag||''))||w.project_id!==job.project_id||
   w.content_id!==job.content_id||w.preview?.verified!==true)
   throw new Error('SM3_07F_V3_WORKSPACE_REVISION_INVALID:'+String(w.edit_session_id));
const gated=$('ASSERT — RENDER READINESS').all().map(i=>i.json).find(i=>i.edit_session_id===w.edit_session_id);
if(!gated||gated.preflight_contract!=='SM3_07F_PREFLIGHT_V2'||gated.verified_revision!==w.current_revision||
  gated.verified_state_etag!==w.state_etag)
  throw new Error('SM3_07F_V3_PREFLIGHT_STATE_CHANGED:'+w.content_id);
const required=new Set([...(w.recipe?.media_order||[]),...(w.recipe?.timeline||[]).map(x=>x.media_id)]);
const sources=job.source_media.filter(x=>required.has(x.media_id));
if(!required.size||required.size!==sources.length||new Set(sources.map(x=>x.media_id)).size!==required.size)
   throw new Error('SM3_07F_V3_RECIPE_SOURCE_MISMATCH:'+w.content_id);
const requested=['logo','stamp','texture','frame'].filter(k=>w.recipe?.identity_application?.[k]===true);
const identity_assets=(gated.identity_assets||[]).map(x=>({asset_id:x.asset_id,role:x.role,source_path:x.source_path,
  file_name:x.file_name,expected_sha256:x.expected_sha256,mime_type:x.mime_type}));
if(identity_assets.length!==requested.length||new Set(identity_assets.map(x=>x.role)).size!==requested.length||
   requested.some(role=>!identity_assets.some(x=>x.role===role)))
  throw new Error('SM3_07F_V3_IDENTITY_BINDING_SET_CHANGED:'+w.content_id);
return {json:{...job,source_media:sources,identity_assets,expected_revision:w.current_revision,
  expected_state_etag:w.state_etag,fps:24,max_seconds:12}};

const m=$json, job=$('ASSERT — REVISION AND SOURCES').all().map(i=>i.json).find(x=>x.edit_session_id===m.edit_session_id);
if(!job||m.ok!==true||m.contract_version!=='SM3_EDIT_PREVIEW_V3'||m.project_id!==job.project_id||
  m.content_id!==job.content_id||m.revision!==job.expected_revision||m.state_etag!==job.expected_state_etag||
  m.preview_bytes<100||m.renderer_version!=='2.8.0'||m.identity_asset_binding_contract!=='SM3_IDENTITY_ASSET_BINDING_V1'||
  !Array.isArray(m.rendered_operations)||!m.rendered_operations.includes('safe_footer_text')||
  !/^[a-f0-9]{64}$/.test(String(m.preview_sha256||''))||m.final_render!==false)
  throw new Error('SM3_07F_V3_RENDER_RESULT_INVALID:'+String(m.edit_session_id));
for(const source of job.source_media)
  if(m.source_hashes?.[source.media_id]!==source.expected_sha256)
    throw new Error('SM3_07F_V3_SOURCE_HASH_NOT_COMMITTED:'+source.media_id);
const expectedRoles=job.identity_assets.map(x=>x.role).sort(), actualRoles=Object.keys(m.identity_asset_hashes||{}).sort();
if(JSON.stringify(expectedRoles)!==JSON.stringify(actualRoles))
  throw new Error('SM3_07F_V3_IDENTITY_ROLE_MANIFEST_MISMATCH:'+m.content_id);
for(const asset of job.identity_assets){
  if(m.identity_asset_hashes?.[asset.role]!==asset.expected_sha256||!m.rendered_operations.includes('identity_'+asset.role))
    throw new Error('SM3_07F_V3_IDENTITY_HASH_OR_OPERATION_MISMATCH:'+asset.role);
}
return {json:{source_hashes:m.source_hashes,identity_asset_hashes:m.identity_asset_hashes,
  project_id:m.project_id,content_id:m.content_id,edit_session_id:m.edit_session_id,revision:m.revision,
  etag:m.state_etag,preview_sha256:m.preview_sha256,sheet_render_status:job.sheet_render_status,
  reused_existing:m.reused_existing===true}};

const v=$json, original=$('ASSERT — RENDER RESULT').all().map(i=>i.json).find(x=>x.edit_session_id===v.edit_session_id);
if(!original||v.ok!==true||v.contract_version!=='SM3_EDIT_PREVIEW_V3'||v.renderer_version!=='2.8.0'||
   v.identity_asset_binding_contract!=='SM3_IDENTITY_ASSET_BINDING_V1'||v.preview_sha256!==original.preview_sha256||
   Object.keys(original.source_hashes||{}).some(k=>v.source_hashes?.[k]!==original.source_hashes[k])||
   Object.keys(original.identity_asset_hashes||{}).some(k=>v.identity_asset_hashes?.[k]!==original.identity_asset_hashes[k])||
   v.state_etag!==original.etag||v.revision!==original.revision||v.content_id!==original.content_id||
   !String(v.asset_url||'').endsWith('/asset'))
   throw new Error('SM3_07F_V3_PERSISTENCE_MISMATCH:'+String(v.edit_session_id));
return {json:{route:original.sheet_render_status==='EDIT_PREVIEW_READY'?'NO_WRITE':'WRITE',
  ID_CONTEÚDO:v.content_id,edit_session_id:v.edit_session_id,revision:v.revision,
  preview_sha256:v.preview_sha256,RENDER_STATUS:'EDIT_PREVIEW_READY',STATE_UPDATED_AT:new Date().toISOString(),
  asset_url:'http://localhost:8090'+v.asset_url,reused_existing:original.reused_existing}};

const rows=$input.all().map(i=>i.json),items=$('ASSERT — PREVIEW COMMITTED').all().map(i=>i.json).filter(x=>x.route==='WRITE');
for(const item of items){const matches=rows.filter(r=>String(r.ID_CONTEÚDO||'')===item.ID_CONTEÚDO);
 if(matches.length!==1||matches[0].RENDER_STATUS!=='EDIT_PREVIEW_READY'||
    matches[0].EDIT_SESSION_STATUS!=='SAVED'||matches[0].REVISION_MODE!=='MANUAL_EDIT'||
    !String(matches[0].STATE_UPDATED_AT||''))
    throw new Error('SM3_07F_SHEET_PERSISTENCE_FAILED:'+item.ID_CONTEÚDO);
}
return [{json:{status:'SM3_07F_EDIT_PREVIEW_VERIFIED_COMMIT',committed_count:items.length,
  previews:items.map(x=>({content_id:x.ID_CONTEÚDO,revision:x.revision,preview_sha256:x.preview_sha256,asset_url:x.asset_url}))}}];

const contents=$('READ — 04_CONTEUDOS').all().map(i=>i.json);
const media=$('READ — 03_MIDIAS').all().map(i=>i.json);
const norm=v=>String(v??'').trim(), up=v=>norm(v).toUpperCase();
const chosen=contents.filter(c=>up(c.EDIT_SESSION_STATUS)==='SAVED'&&
  up(c.REVISION_MODE)==='MANUAL_EDIT'&&up(c.PIPELINE_STATE)==='EDIT_SESSION_READY');
if(!chosen.length)return [{json:{route:'NO_WORK'}}];
const counts=new Map(),mcounts=new Map(),sessions=new Set();
for(const c of contents){const id=norm(c.ID_CONTEÚDO);if(id)counts.set(id,(counts.get(id)||0)+1)}
for(const m of media){const id=norm(m.ID_MIDIA);if(id)mcounts.set(id,(mcounts.get(id)||0)+1)}
return chosen.map(c=>{
  const content_id=norm(c.ID_CONTEÚDO),project_id=norm(c.ID_PROJETO),
    edit_session_id=norm(c.EDIT_SESSION_ID),ids=[...new Set(norm(c.BRUTOS_USADOS).match(/M\d{4,}/g)||[])];
  if(counts.get(content_id)!==1||sessions.has(edit_session_id)||!ids.length||
    !/^TATTOO_[A-Za-z0-9_-]+$/.test(project_id)||
    !/^ES_[A-Za-z0-9_-]+$/.test(edit_session_id)||
    up(c.STATE_VERSION)!=='SM3_STATE_V5'||
    norm(c.EDIT_RECIPE_VERSION)!=='SM3_EDIT_RECIPE_V1'||
    norm(c.PRODUCTION_CONTRACT_VERSION)!=='SM3_PRODUCTION_EDIT_V1'||
    ids.some(id=>mcounts.get(id)!==1))
    throw new Error('SM3_07F_PREFLIGHT_SHEET_CONTRACT_INVALID:'+content_id);
  sessions.add(edit_session_id);
  return {json:{route:'CHECK',project_id,content_id,edit_session_id,
    media_ids:ids,sheet_render_status:norm(c.RENDER_STATUS)}};
});

const w=$json, jobs=$('BUILD — PREFLIGHT SESSIONS').all().map(i=>i.json),
  job=jobs.find(j=>j.edit_session_id===w.edit_session_id),
  media=$('READ — 03_MIDIAS').all().map(i=>i.json),
  assets=$('READ — 07_ATIVOS_IDENTIDADE').all().map(i=>i.json);
const norm=v=>String(v??'').trim(), up=v=>norm(v).toUpperCase();
if(!job||jobs.filter(j=>j.edit_session_id===w.edit_session_id).length!==1||
  w.ok!==true||w.status!=='SAVED'||w.current_revision<3||w.read_only!==false||
  w.workspace_contract_version!=='SM3_EDITOR_WORKSPACE_V1'||
  !/^[a-f0-9]{64}$/.test(norm(w.state_etag))||
  w.project_id!==job.project_id||w.content_id!==job.content_id||w.preview?.verified!==true)
  throw new Error('SM3_07F_V3_WORKSPACE_REVISION_INVALID:'+String(w.edit_session_id));
const r=w.recipe,blockers=[],add=(code,detail)=>blockers.push({code,detail});
if(!r||typeof r!=='object')throw new Error('SM3_07F_V3_RECIPE_MISSING');
const ids=r.media_order||[],timeline=r.timeline||[],unique=new Set(ids),
  needed=new Set([...ids,...timeline.map(s=>s.media_id)]);
if(!ids.length||unique.size!==ids.length||timeline.length!==ids.length||
   timeline.some((s,i)=>s.media_id!==ids[i])||[...needed].some(id=>!job.media_ids.includes(id)))
  add('RECIPE_MEDIA_OR_TIMELINE_INVALID',String(ids));
for(const id of needed){
  const matches=media.filter(m=>norm(m.ID_MIDIA)===id);
  if(matches.length!==1)add('MEDIA_REGISTRY_NOT_UNIQUE',id);
  else {
    if(!norm(matches[0].DRIVE_FILE_ID))add('MEDIA_DRIVE_ID_MISSING',id);
    if(!/^[a-f0-9]{64}$/.test(norm(matches[0].CONTENT_HASH).toLowerCase()))
      add('MEDIA_CONTENT_SHA256_MISSING',id);
  }
}
for(const t of r.text_overlays||[]){
  const match=/^SAFE_FOOTER:(M\d{4,})$/.exec(norm(t.placement));
  if(!match||!unique.has(match[1])||t.start_seconds!==null||t.end_seconds!==null)
    add('TEXT_PLACEMENT_OR_TIMING_INVALID',norm(t.placement));
}
const identity=r.identity_application||{};
if(identity.density!=='NONE')
  add('IDENTITY_AUTO_DENSITY_NOT_EXECUTABLE','Explicit bindings are supported; automatic density remains fail-closed');
const requested=['logo','stamp','texture','frame'].filter(role=>identity[role]===true);
const identity_assets=[];
for(const role of requested){
  const matches=assets.filter(a=>norm(a.BINDING_ROLE).toLowerCase()===role&&
    up(a.BINDING_STATUS)==='DEFAULT');
  if(matches.length!==1){add('IDENTITY_DEFAULT_BINDING_NOT_UNIQUE',role+':'+matches.length);continue}
  const a=matches[0], assetId=norm(a.ID_ATIVO), driveId=norm(a.ID_DRIVE),
    hash=norm(a.CONTENT_HASH).toLowerCase(), mime=norm(a.MIME_TYPE).toLowerCase(), type=up(a.TIPO);
  if(!/^[A-Za-z0-9_-]{2,100}$/.test(assetId))add('IDENTITY_ASSET_ID_INVALID',role);
  if(!driveId)add('IDENTITY_DRIVE_ID_MISSING',role+':'+assetId);
  if(!/^[a-f0-9]{64}$/.test(hash))add('IDENTITY_CONTENT_SHA256_MISSING',role+':'+assetId);
  if(type!=='PNG'||mime!=='image/png')add('IDENTITY_RASTER_BINDING_REQUIRED',role+':'+assetId+':'+type+':'+mime);
  const safe=norm(a.NOME||assetId+'.png').replace(/[^A-Za-z0-9._-]+/g,'_').slice(-100);
  identity_assets.push({asset_id:assetId,role,drive_file_id:driveId,file_name:safe,
    source_path:'/data/media/inbox/identity_'+assetId+'_'+safe,expected_sha256:hash,mime_type:mime});
}
if(identity_assets.length!==requested.length)add('IDENTITY_BINDING_SET_INCOMPLETE',requested.join(','));
const color=r.color_treatment||{};
if(color.style!=='DOCUMENTARY_NEUTRAL_PREVIEW')add('COLOR_STYLE_NOT_EXECUTABLE',norm(color.style));
for(const [key,low,high] of [['exposure_delta',-.3,.3],['contrast_delta',-.4,.6],['saturation_delta',-1,1]]){
  const x=color[key];if(typeof x!=='number'||!Number.isFinite(x)||x<low||x>high)
    add('COLOR_UNIT_OR_RANGE_INVALID',`${key}=${String(x)} accepted=[${low},${high}]`);
}
if(!['CUT','HARD_CUT','NONE'].includes(up(r.transition_style)))add('TRANSITION_NOT_EXECUTABLE',norm(r.transition_style));
if(!['ORIGINAL_MUTED','MUTED','NONE','SILENT'].includes(up(r.audio_strategy)))add('AUDIO_NOT_EXECUTABLE',norm(r.audio_strategy));
const framing=r.framing||[];
if(framing.length!==ids.length||new Set(framing.map(f=>f.media_id)).size!==ids.length)
  add('FRAMING_SET_INVALID',String(framing.length));
for(const f of framing){
  if(f.preserve_subject!==true||String(f.mode||'').toUpperCase()!=='CONTAIN'||f.zoom_start!==1||f.zoom_end!==1)
    add('CROP_OR_ZOOM_REQUIRES_VERIFIED_GEOMETRY',String(f.media_id));
}
if(blockers.length)throw new Error('SM3_07F_V3_RENDER_CONTRACT_BLOCKED:'+w.content_id+
  ':REV'+w.current_revision+':'+JSON.stringify(blockers));
return {json:{...job,verified_revision:w.current_revision,verified_state_etag:w.state_etag,
  identity_assets,requested_identity_roles:requested,preflight_contract:'SM3_07F_PREFLIGHT_V2'}};

const gated=$input.all().map(i=>i.json);
const queue=[];
for(const g of gated){
  for(const a of (g.identity_assets||[])) queue.push({route:'DOWNLOAD',edit_session_id:g.edit_session_id,
    asset_id:a.asset_id,role:a.role,DRIVE_FILE_ID:a.drive_file_id,ARQUIVO:a.file_name,
    worker_source_path:a.source_path,expected_sha256:a.expected_sha256,mime_type:a.mime_type});
}
if(!queue.length)return [{json:{route:'NO_IDENTITY'}}];
const keys=new Set();
for(const a of queue){const key=a.edit_session_id+'|'+a.role;if(keys.has(key))throw new Error('SM3_07F_V3_IDENTITY_QUEUE_DUPLICATE:'+key);keys.add(key)}
return queue.map(json=>({json}));
